function Show-ServiceManager {do{Show-Header;Write-Host "GERENCIAR SERVICOS OPCIONAIS" -ForegroundColor Yellow;Write-Host "[1] Ver status de telemetria, WER e Xbox";Write-Host "[2] Desativar somente servicos Xbox";Write-Host "[3] Restaurar servicos Xbox para Manual";Write-Host "[4] Restaurar DiagTrack/dmwappushservice para Manual";Write-Host "[5] Restaurar WerSvc para Manual";Write-Host "[0] Voltar";$o=Read-Host "Opcao";switch($o){"1"{Get-Service DiagTrack,dmwappushservice,WerSvc,XblAuthManager,XblGameSave,XboxNetApiSvc,XboxGipSvc -ErrorAction SilentlyContinue|Select-Object Name,Status,StartType|Format-Table -AutoSize;Pause-WinOptimizer};"2"{if(Confirm-WinOptimizerAction "Voce nao usa Xbox/Game Pass? Desativar servicos Xbox?"){Set-OptionalServiceState @("XblAuthManager","XblGameSave","XboxNetApiSvc","XboxGipSvc");Save-AppliedChange Servicos "Xbox desativado" "Servicos Xbox configurados como Disabled."};Pause-WinOptimizer};"3"{foreach($s in "XblAuthManager","XblGameSave","XboxNetApiSvc","XboxGipSvc"){Set-Service $s -StartupType Manual -ErrorAction SilentlyContinue};Write-Status "Servicos Xbox restaurados para Manual." Green;Pause-WinOptimizer};"4"{foreach($s in "DiagTrack","dmwappushservice"){Set-Service $s -StartupType Manual -ErrorAction SilentlyContinue};Write-Status "Servicos de telemetria restaurados para Manual." Green;Pause-WinOptimizer};"5"{Set-Service WerSvc -StartupType Manual -ErrorAction SilentlyContinue;Write-Status "WerSvc restaurado para Manual." Green;Pause-WinOptimizer};"0"{break}}}while($o -ne "0")}
